// Hand-authored shared helpers for the scientific-consensus engines. Not
// generated; safe across regeneration (no "Generated by" header).
package cli

import (
	"context"
	"encoding/json"
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"github.com/mvanhorn/printing-press-library/library/other/scientific-consensus/internal/scengine"
	"github.com/mvanhorn/printing-press-library/library/other/scientific-consensus/internal/source"
)

// scWork is the normalized work record the engines operate on. It is populated
// primarily from OpenAlex and optionally enriched from secondary sources.
type scWork struct {
	ID       string `json:"id"`
	DOI      string `json:"doi,omitempty"`
	PMID     string `json:"pmid,omitempty"`
	Title    string `json:"title"`
	Abstract string `json:"-"`
	Year     int    `json:"year,omitempty"`
	Type     string `json:"type,omitempty"`
	CitedBy  int    `json:"cited_by_count"`
	Venue    string `json:"venue,omitempty"`
	Topic    string `json:"topic,omitempty"`
	IsOA     bool   `json:"is_oa,omitempty"`
	// IsRetracted is the source index's retraction flag, carried raw from
	// OpenAlex is_retracted. It is one of the two inputs to
	// scengine.DetectRetraction; the derived status lives in Retraction.
	IsRetracted bool `json:"-"`
	// Retraction is the derived retraction status, set by filterRetracted.
	// Empty (scengine.NotRetracted) for every work with no signal, so the
	// field is absent from JSON for the overwhelming majority of works.
	Retraction  scengine.Retraction `json:"retraction,omitempty"`
	PubTypes    []string            `json:"-"`
	FirstAuthor string              `json:"first_author,omitempty"`
	// Authors is every authorship display name in the order OpenAlex
	// returned them. Empty when the work has no authorships.
	Authors []string `json:"authors,omitempty"`
	Country string   `json:"-"`
}

// openAlexWorksResponse mirrors the slice of the OpenAlex /works payload the
// engines need.
type openAlexWorksResponse struct {
	Meta struct {
		Count int `json:"count"`
	} `json:"meta"`
	Results []openAlexWork `json:"results"`
	GroupBy []struct {
		Key            string `json:"key"`
		KeyDisplayName string `json:"key_display_name"`
		Count          int    `json:"count"`
	} `json:"group_by"`
}

type openAlexWork struct {
	ID              string `json:"id"`
	DOI             string `json:"doi"`
	Title           string `json:"title"`
	DisplayName     string `json:"display_name"`
	PublicationYear int    `json:"publication_year"`
	CitedByCount    int    `json:"cited_by_count"`
	Type            string `json:"type"`
	IsRetracted     bool   `json:"is_retracted"`
	OpenAccess      struct {
		IsOA bool `json:"is_oa"`
	} `json:"open_access"`
	AbstractInvertedIndex map[string][]int `json:"abstract_inverted_index"`
	IDs                   struct {
		Pmid string `json:"pmid"`
	} `json:"ids"`
	PrimaryTopic struct {
		DisplayName string `json:"display_name"`
	} `json:"primary_topic"`
	PrimaryLocation struct {
		Source struct {
			DisplayName string `json:"display_name"`
		} `json:"source"`
	} `json:"primary_location"`
	Authorships []struct {
		Author struct {
			DisplayName string `json:"display_name"`
		} `json:"author"`
		Institutions []struct {
			CountryCode string `json:"country_code"`
		} `json:"institutions"`
	} `json:"authorships"`
}

// defaultMailto is OpenAlex's polite-pool courtesy parameter.
const defaultMailto = "scientific-consensus-pp-cli@users.noreply.github.com"

// fetchWorks queries OpenAlex /works and returns normalized works. search is the
// query; filter is an optional OpenAlex filter expression; perPage caps results
// (<=200). Abstracts are reconstructed from the inverted index.
func fetchWorks(ctx context.Context, c apiGetter, search, filter, sortBy string, perPage int) ([]scWork, int, error) {
	if perPage <= 0 {
		perPage = 50
	}
	if perPage > 200 {
		perPage = 200
	}
	params := map[string]string{
		"per-page": strconv.Itoa(perPage),
		"mailto":   defaultMailto,
		// is_retracted is requested explicitly: without it the field is absent
		// from every result and scengine.DetectRetraction degrades to the
		// title rule alone, which misses index-only retractions.
		"select": "id,doi,title,display_name,publication_year,cited_by_count,type,open_access,abstract_inverted_index,ids,primary_topic,primary_location,authorships,is_retracted",
	}
	if search != "" {
		params["search"] = search
	}
	if filter != "" {
		params["filter"] = filter
	}
	if sortBy != "" {
		params["sort"] = sortBy
	}
	raw, err := c.Get(ctx, "/works", params)
	if err != nil {
		return nil, 0, err
	}
	var resp openAlexWorksResponse
	if err := json.Unmarshal(raw, &resp); err != nil {
		return nil, 0, fmt.Errorf("parsing OpenAlex works: %w", err)
	}
	out := make([]scWork, 0, len(resp.Results))
	for _, w := range resp.Results {
		title := w.Title
		if title == "" {
			title = w.DisplayName
		}
		sw := scWork{
			ID:       w.ID,
			DOI:      strings.TrimPrefix(w.DOI, "https://doi.org/"),
			PMID:     extractPMID(w.IDs.Pmid),
			Title:    title,
			Abstract: scengine.ReconstructAbstract(w.AbstractInvertedIndex),
			Year:     w.PublicationYear,
			Type:     w.Type,
			CitedBy:  w.CitedByCount,
			Venue:    w.PrimaryLocation.Source.DisplayName,
			Topic:    w.PrimaryTopic.DisplayName,
			IsOA:     w.OpenAccess.IsOA,
			// Carried raw rather than resolved here: detection needs the title
			// too, and filterRetracted is the single place that runs it, so
			// works built by other paths get the same treatment.
			IsRetracted: w.IsRetracted,
		}
		if len(w.Authorships) > 0 {
			sw.FirstAuthor = w.Authorships[0].Author.DisplayName
			for _, a := range w.Authorships {
				if a.Author.DisplayName != "" {
					sw.Authors = append(sw.Authors, a.Author.DisplayName)
				}
			}
			for _, inst := range w.Authorships[0].Institutions {
				if inst.CountryCode != "" {
					sw.Country = inst.CountryCode
					break
				}
			}
		}
		out = append(out, sw)
	}
	return out, resp.Meta.Count, nil
}

// fetchGroupBy runs an OpenAlex group_by facet query against the given entity
// path (e.g. "/works", "/authors") and returns the facet rows.
func fetchGroupBy(ctx context.Context, c apiGetter, path, search, filter, groupBy string) ([]groupRow, error) {
	params := map[string]string{
		"group_by": groupBy,
		"mailto":   defaultMailto,
		"per-page": "200",
	}
	if search != "" {
		params["search"] = search
	}
	if filter != "" {
		params["filter"] = filter
	}
	raw, err := c.Get(ctx, path, params)
	if err != nil {
		return nil, err
	}
	var resp openAlexWorksResponse
	if err := json.Unmarshal(raw, &resp); err != nil {
		return nil, fmt.Errorf("parsing group_by: %w", err)
	}
	out := make([]groupRow, 0, len(resp.GroupBy))
	for _, g := range resp.GroupBy {
		name := g.KeyDisplayName
		if name == "" {
			name = g.Key
		}
		out = append(out, groupRow{Key: g.Key, Name: name, Count: g.Count})
	}
	return out, nil
}

type groupRow struct {
	Key   string `json:"key"`
	Name  string `json:"name"`
	Count int    `json:"count"`
}

// classifyWorks runs the evidence classifier over a slice of works, using any
// PubTypes already attached.
func classifyWorks(works []scWork) []scengine.Classification {
	cs := make([]scengine.Classification, len(works))
	for i, w := range works {
		cs[i] = scengine.ClassifyDesign(w.Title, w.Abstract, w.Type, w.PubTypes)
	}
	return cs
}

// scoreWorks builds the consensus engine input from works + per-work stance.
// ctx bounds the optional per-work LLM stance calls so --timeout and Ctrl+C
// propagate; the heuristic path never blocks on it.
func scoreWorks(ctx context.Context, works []scWork, claim string) ([]scengine.ScoredWork, []workStance) {
	scored := make([]scengine.ScoredWork, len(works))
	stances := make([]workStance, len(works))
	for i, w := range works {
		cls := scengine.ClassifyDesign(w.Title, w.Abstract, w.Type, w.PubTypes)
		st, conf, stMethod := scengine.ClassifyStanceAuto(ctx, w.Title, w.Abstract, claim)
		scored[i] = scengine.ScoredWork{Stance: st, StanceConf: conf, Design: cls.Design, CitedBy: w.CitedBy}
		stances[i] = workStance{Work: w, Stance: st, Confidence: conf, Design: cls.Design, Method: cls.Method, StanceMethod: stMethod}
	}
	return scored, stances
}

type workStance struct {
	Work       scWork          `json:"work"`
	Stance     scengine.Stance `json:"stance"`
	Confidence float64         `json:"stance_confidence"`
	Design     scengine.Design `json:"design"`
	Method     scengine.Method `json:"classification_method"`
	// StanceMethod records how stance was derived: "heuristic" or
	// "llm:<provider>". Empty for callers that don't run the dispatcher.
	StanceMethod string `json:"stance_method,omitempty"`
}

// relevantToClaim reports whether a work's Title or Topic shares at least one
// content token with the claim (stopword- and polarity-word-stripped, stemmed
// to five characters so inflected forms match). Conservative by design: a
// claim that yields no content tokens disables the gate (keep everything),
// and a single token overlap is enough to keep a work — the gate exists to
// drop clearly off-topic results (a crop-genetics paper under a
// coffee/alertness claim), not to rank relevance.
func relevantToClaim(claim string, w scWork) bool {
	tokens := scengine.ClaimContentTokens(claim)
	if len(tokens) == 0 {
		return true
	}
	hay := strings.ToLower(w.Title + " " + w.Topic)
	for _, tok := range tokens {
		stem := tok
		if len(stem) > 5 {
			stem = stem[:5]
		}
		if strings.Contains(hay, stem) {
			return true
		}
	}
	return false
}

// filterRelevant drops works that fail the relevance gate so they never reach
// classification or scoring. Returns a new slice; the input is not mutated.
//
// Two gates are available and this is the single place that chooses between
// them. The PICO gate is preferred: it requires a work to name BOTH sides of
// the claim (an intervention token AND an outcome token), and it reads the
// abstract, so it judges what a paper is actually about rather than what its
// title happens to mention. It applies only when the claim can be split around
// a polarity verb; PICOTokens returns empty slices when it cannot.
//
// When the claim is not splittable the token-overlap gate runs instead. That
// case is not rare, and dropping the older gate outright would leave those
// claims with no relevance filtering at all, which is the opposite of this
// change's purpose. The two are alternatives, not layers: running both would
// apply a title/topic rule on top of an abstract-aware one and silently
// re-drop works the PICO gate deliberately kept.
//
// When PICOTokens cannot split the claim and an LLM key is configured,
// claimSplit tries an LLM split before giving up on the PICO gate. Any failure
// lands back on the token-overlap gate. The returned label names the gate that
// ran, for output next to stance_method; it is empty when there were no works
// to filter, which also avoids paying for a split nothing would use.
func filterRelevant(ctx context.Context, claim string, works []scWork) ([]scWork, string) {
	if len(works) == 0 {
		return []scWork{}, ""
	}
	ivTokens, outTokens, gate := claimSplit(ctx, claim)
	usePICO := len(ivTokens) > 0 && len(outTokens) > 0
	kept := make([]scWork, 0, len(works))
	for _, w := range works {
		var relevant bool
		if usePICO {
			relevant = scengine.IsPICORelevant(w.Abstract, w.Title, ivTokens, outTokens)
		} else {
			relevant = relevantToClaim(claim, w)
		}
		if relevant {
			kept = append(kept, w)
		}
	}
	return kept, gate
}

// claimSplit is a variable so tests can stub the provider-backed split.
var claimSplit = scengine.ClaimSplitAuto

// nonAlnumRun matches a run of characters that are not a lowercase ASCII
// letter or digit; normalizedTitle collapses each run to one space.
var nonAlnumRun = regexp.MustCompile(`[^a-z0-9]+`)

// normalizedTitle lowercases a title, replaces every run of non [a-z0-9]
// characters with one space and trims the result, so a curly and a straight
// apostrophe (or any other punctuation difference) compare equal.
func normalizedTitle(title string) string {
	return strings.TrimSpace(nonAlnumRun.ReplaceAllString(strings.ToLower(title), " "))
}

// propagateRetractionToTwins gives scengine.RetractionTwin, in place, to every
// NotRetracted work that shares a normalized title and a publication year with
// a work that already carries a retraction status. The same paper is often
// indexed twice (one copy with a DOI and the index flag, one without), and
// DetectRetraction sees one work at a time. Works with Year == 0 or an empty
// normalized title never give or receive a mark, and RetractionDeclared and
// RetractionFlagged are never overwritten. The outcome does not depend on the
// order of works.
func propagateRetractionToTwins(works []scWork) {
	retracted := map[string]bool{}
	keyOf := func(w scWork) (string, bool) {
		t := normalizedTitle(w.Title)
		if w.Year == 0 || t == "" {
			return "", false
		}
		return t + "|" + strconv.Itoa(w.Year), true
	}
	for _, w := range works {
		if key, ok := keyOf(w); ok && w.Retraction != scengine.NotRetracted {
			retracted[key] = true
		}
	}
	for i := range works {
		if key, ok := keyOf(works[i]); ok && works[i].Retraction == scengine.NotRetracted && retracted[key] {
			works[i].Retraction = scengine.RetractionTwin
		}
	}
}

// markRetractions returns a copy of works with Retraction set on every work:
// DetectRetraction on its title and index flag, then propagateRetractionToTwins
// across the whole slice. Run it on the fetched works BEFORE filterRelevant, so
// a copy the relevance gate drops (the gate reads the abstract, which two
// copies of one paper may not share) still marks its surviving twin. Input is
// not mutated. filterRetracted keeps the status it stamps.
func markRetractions(works []scWork) []scWork {
	marked := make([]scWork, len(works))
	for i, w := range works {
		w.Retraction = scengine.DetectRetraction(w.Title, w.IsRetracted)
		marked[i] = w
	}
	propagateRetractionToTwins(marked)
	return marked
}

// filterRetracted partitions works by retraction status, running
// scengine.DetectRetraction on both available signals: the title alone (never
// title+abstract joined — the marker pattern is start-anchored) and the source
// index flag carried in IsRetracted. DetectRetraction sees one work at a time,
// so a second pass (propagateRetractionToTwins) marks any still-unflagged copy
// of a retracted work in the same result — same normalized title, same year —
// as scengine.RetractionTwin before the partition.
//
// It follows filterRelevant: a pre-scoring gate that returns new slices and
// does not mutate its input. It differs in also returning the excluded works,
// because a retracted work must stay visible in the study list with its reason
// attached (the PRISMA convention retracted.go's ExcludeFromScore documents),
// whereas an off-topic work is simply not about the claim.
//
// The derived status is stamped onto both returned slices, so NotRetracted
// works carry an explicit empty value and callers never re-run the detector.
func filterRetracted(works []scWork) (kept, excluded []scWork) {
	kept = make([]scWork, 0, len(works))
	detected := make([]scWork, len(works))
	for i, w := range works {
		// A status already stamped by markRetractions is kept, so a twin
		// mark given before the relevance gate is not recomputed away.
		if w.Retraction == scengine.NotRetracted {
			w.Retraction = scengine.DetectRetraction(w.Title, w.IsRetracted)
		}
		detected[i] = w
	}
	propagateRetractionToTwins(detected)
	for _, w := range detected {
		if w.Retraction.ExcludeFromScore() {
			excluded = append(excluded, w)
			continue
		}
		kept = append(kept, w)
	}
	return kept, excluded
}

// extractPMID pulls the numeric PMID out of an OpenAlex pmid URL.
func extractPMID(u string) string {
	if u == "" {
		return ""
	}
	i := strings.LastIndex(u, "/")
	if i >= 0 && i < len(u)-1 {
		return u[i+1:]
	}
	return u
}

// sortWorksByCitations sorts descending by citation count (stable).
func sortWorksByCitations(works []scWork) {
	sort.SliceStable(works, func(i, j int) bool { return works[i].CitedBy > works[j].CitedBy })
}

// apiGetter is the subset of *client.Client the engines need. Declared as an
// interface so engine helpers can be unit-tested with a stub.
type apiGetter interface {
	Get(ctx context.Context, path string, params map[string]string) (json.RawMessage, error)
}

// enrichPubTypes best-effort augments works that have a PMID with authoritative
// PubMed publication types. Errors are swallowed (enrichment is optional). cap
// bounds how many PMIDs are looked up to keep latency bounded.
func enrichPubTypes(ctx context.Context, works []scWork, capN int) {
	pmids := make([]string, 0, len(works))
	idx := map[string]int{}
	for i := range works {
		if works[i].PMID != "" && len(pmids) < capN {
			pmids = append(pmids, works[i].PMID)
			idx[works[i].PMID] = i
		}
	}
	if len(pmids) == 0 {
		return
	}
	types, err := source.PubMedPubTypes(ctx, pmids)
	if err != nil {
		return
	}
	for pmid, pts := range types {
		if i, ok := idx[pmid]; ok {
			works[i].PubTypes = pts
		}
	}
}
